import functools
import warnings

def deprecated(message):
    """Decorator to mark functions and methods as deprecated.

    Args:
        message (str): Deprecation message to display.

    Returns:
        Callable: Wrapped function that issues a DeprecationWarning when called.
    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

