import re

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args.

    Supports placeholders in the form :key or {key}. Values are taken from
    the `url_args` mapping. Raises a KeyError if a placeholder key is
    missing in the mapping.
    """
    if not isinstance(url, str):
        raise TypeError("url must be a string")

    if url_args is None:
        url_args = {}

    # pattern matches either :key or {key}
    pattern = re.compile(r":(?P<key>\w+)|\{(?P<key>\w+)\}")

    def repl(match):
        key = match.group("key")
        if key not in url_args:
            raise KeyError(f"Missing URL argument: {key!r}")
        return str(url_args[key])

    return pattern.sub(repl, url)

